function MainQuestMapMgr:FillQuestInfo(questId)
    if isNull(self._parGo) then
        return
    end

    local vo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(questId)
    if not vo then
        return
    end
    self:FillMap(vo)
    self:FillCamera(vo)
    self:FillHeadsInfo(vo)
    self:FillWeather(vo)
end 

function MainQuestMapMgr:FillCamera(vo)
    if isNull(self._camGo) then
        return
    end
    local mainQuestHeadGroupInfoVo = self:GetMmainQuestHeadGroupInfoVo(vo.headGroupPos)
    if mainQuestHeadGroupInfoVo then
        self._camGo.transform.localPosition = Vector3(mainQuestHeadGroupInfoVo.mapTransformPX, mainQuestHeadGroupInfoVo.mapTransformPY, mainQuestHeadGroupInfoVo.mapTransformPZ)
        self._camGo.transform.localRotation = Quaternion.Euler(mainQuestHeadGroupInfoVo.mapTransformRX, mainQuestHeadGroupInfoVo.mapTransformRY, mainQuestHeadGroupInfoVo.mapTransformRZ)
    end

    local urpBase = self._camGo:GetComponent(typeof(URPBaseCamera))
    urpBase:CopyCamera()
end

function MainQuestMapMgr:RefreshCam()
    --KTool.SetActive(self._parGo.gameObject, true)
