    urpBase:CopyCamera()
end

function MainQuestMapMgr:FillWeather(vo)
    --local name = "Movie/op_rain_loop_01.usm"
    if not vo then
        return
    end
    local go = self:GetWeatherGo()
    if isNull(go) then
        return
    end

    local controllerForUI = go.transform:Find("Movie"):GetComponent(typeof(CS.CriWare.CriManaMovieControllerForUI))

    vo = QuestConfMgr:GetInstance():GetWeatherVo(vo.weather)
    if not vo then
        --KTool.SetActive(go, false)
