        go.transform.localPosition = Vector3(9999, 9999, 0)
    else
        --KTool.SetActive(go, true)
        controllerForUI.player:SetFile(nil, GameUtils.GetManaPath(vo.image))
        controllerForUI:Play()
        go.transform.localPosition = Vector3(0, 0, 0)
