    end
end

function MainQuestMapMgr:GetWeatherGo()
    if not isNull(self._weatherGo) then
        return self._weatherGo
    end

    if isNull(self._weatherLoader) then
        self._weatherLoader = ResourceModule.LoadBundleSync("Prefabs/MainChapter/CriMovieNode.prefab")
        if self._weatherLoader.IsSuccess then
        else
            self._weatherLoader:Release()
            self._weatherLoader = nil
        end
    end
    if isNull(self._weatherLoader) then
        return nil
    end
    self._weatherGo = CfUtils.InstantiateGo(self._weatherLoader.ResultObject.gameObject, UIModule.RootCanvas.gameObject)
    local controllerForUI = self._weatherGo.transform:Find("Movie"):GetComponent(typeof(CS.CriWare.CriManaMovieControllerForUI))
    return self._weatherGo
end

--头像
function MainQuestMapMgr:FillHeadsInfo(vo)
    self:CollectionHeadInfo()

    --[[
    local t = self:GetQuestHeads(vo.id)
    for k, v in pairs(t) do
        local vo = self:GetMmainQuestHeadVo(v)
        self:FillHeadInfo(vo)
    end
    ]]
    if string.isEmpty(vo.head) then
        return
    end
    local t = CfUtils.Split(vo.head)
    if not t or table.count(t) <= 0 then
        return
    end

    for k, v in pairs(t) do
        local path = self:GetHeadPath(v)
        self:FillHeadInfo(path, v, vo.headGroup, k)
    end

    local mainQuestHeadGroupInfoVo = self:GetMmainQuestHeadGroupInfoVo(vo.headGroupPos)
    if mainQuestHeadGroupInfoVo then
        self._headParGo.transform.position = Vector3(mainQuestHeadGroupInfoVo.posX, mainQuestHeadGroupInfoVo.posY, mainQuestHeadGroupInfoVo.posZ)
    end
end

function MainQuestMapMgr:GetHeadPosVo(groupId, pos)
    local tableName = string.format("%sIDGroup", AutoIds.IdSetting2535)
    local id = CfUtils.GetStringIdGroupData(tableName, groupId.."_"..pos)
    local vo = self:GetMmainQuestHeadPosInfoVo(id)
    return vo
end

function MainQuestMapMgr:GetHeadPath(id)
    id = checkNumber(id)
    if id <= 0 then
        return
    end

    local vo = self:GetMmainQuestHeadInfoVo(id)
    if not vo then
        return nil
    end
    if id == 1 then
        if self._gender == GENDER.FEMALE then
            return vo.femaleHead
        else
            return vo.maleHead
        end
    else
        return vo.head
    end
    return nil
end

function MainQuestMapMgr:FillHeadInfo(path, id, groupId, pos)
    if not path then
        return
    end

    local go = self:GetGo(path)
    if isNull(go) then
        return
    end
    local posVo = self:GetHeadPosVo(groupId, pos)
    local v3 = Vector3(0, 0, 0)
    if posVo then
        v3 = Vector3(posVo.posX, posVo.posY, posVo.posZ)
    end

    go.transform.localPosition = v3
    go.transform.localScale = Vector3(0.2, 0.2, 0.2)
    KTool.SetActive(go, true)

    --CfUtils.PlaySpine(go, "animation", true)
    --添加到缓冲
    table.insert(self._curHeadInfo, {
        path = path, 
        id = id,
        go = go,
    })
end
