--op关
function MainQuestMapMgr:EnterQuestOp(id, arg, startCallback)
    self:PlayQuestStory(id, 1, function()
        local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
        if not vo then
            return
        end

        if checkNumber(vo.type) == Constants.QuestBattleType.Story then
            --第四关特殊处理
            if id == Constants.QUEST_OP_LEVEL[4] then
                local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(vo.id)
                local plotIds = CfUtils.Split(plotVo.plotIdGroup2)
                if table.count(plotIds) > 0 then
                    cs_coroutine.start(function()
                        -- 卸载第三关战斗
                        cs_coroutine.yield_return(self:ExitOP3Battle())
                        -- 提前加载创角场景
                        SceneManagement:GetInstance():AppendScene(Constants.IdSceneSetting32,false)
                        -- 第四关创角前有1段剧情
                        self.curPlotIndex = 1
                        self:PlayPloting({plotIds[1], plotIds[2]}, vo, function() 
                            -- 去创角 
                            -- GameUtils.BattleToOtherDialog(Constants.UITypeIds.GameCreateRole, { plotIds = plotIds, id = id, continueIndex = 3})
                            UIModule.OpenDialog({ id = Constants.UITypeIds.GameCreateRole, parameters = { args = { plotIds = plotIds, id = id, continueIndex = 3} } })
                        end, function()
                            if self.curPlotIndex == 1 then
                                if startCallback then
                                    startCallback()
                                end
                                GameUtils.HideBlack(0.3)    -- 序章3最后一段剧情添加了白屏，这里关闭白屏
                            end
                        end)
                    end)
                    
                end
            else
                self:PlayPlot(vo, function()
                    local questComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.QuestComponent)
                    questComponent:StoryEnterReq(id, function()
                        -- 如果是点了跳到op4的按钮，直接去op4
                        local skip2Op4 = GameUtils.LoadInt("skip2Op4", 0) == 2
                        if skip2Op4 then
                            GameUtils.SaveInt("skip2Op4", 3)
                            local op4QuestId = Constants.QUEST_OP_LEVEL[4]
                            self:EnterQuestOp(op4QuestId, nil, startCallback)
                        else
                            local curOp = QuestConfMgr:GetInstance():GetCurOpId()
                            if (curOp ~= 0) then
                                self:EnterQuestOp(curOp, nil, startCallback)
                            else
                                GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, {}, Constants.LoadingType.MainHome, true)
                            end
                        end
                    end)
                end, nil, nil, startCallback)
            end
        else
            local co = FightPreWarMgr:GetInstance():GuideFightEnter(id, arg)
            if co and startCallback then
                cs_coroutine.start(function()
                    cs_coroutine.yield_return(co)
                    if startCallback then
                        startCallback()
                    end
                end)
            else
                if startCallback then
                    startCallback()
                end
            end
        end
    end)
end

function MainQuestMapMgr:ExitOP3Battle()
    if isNull(BattleViewMgr) then
        return
    end
    FightPreWarMgr:GetInstance():ClearBattleBuff()
    if BattleViewMgr then
        BattleViewMgr:SetCameraVMActive(false)
        BattleViewMgr:ResetOutsetBattleSettings()
    end
    if BattleEndMgr then
        --- 结算表演的timeline会改镜头焦距，需要在打开主场景之前先重置掉才行
        BattleEndMgr:ResetCameraAndLight()
    end

    xpcall(function()
        if BattleViewMgr then
            BattleViewMgr:OnDestroy()
            BattleViewMgr = nil
        end
        CS.UnityEngine.LightmapSettings.lightProbes = nil
    end, function(err)
        local nativeFXMgr = CS.Game.Native.ParticleManager.Instance
        nativeFXMgr:TearDown()
        printError(tostring(err))
    end)

    local coWait = CoWait.Start()
    local count = UIModule.CurrentScreen.dialogs.Count
    xTry(function()
        for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
            if not isNull(v) then
                local co = UIModule.CloseDialog(v, true)
                if not isNull(co) then
                    coWait:Coroutine(co)
                end
            end
        end
        UIModule.CurrentScreen.dialogs:Clear()
    end)
    while not coWait.IsFinish and count > 0 do
        coroutine.yield()
    end
end

--播放剧情
function MainQuestMapMgr:PlayPlot(vo, endCb, isTask, taskStoryType, startCallback)
    if not vo then
        return
    end
    if self.isPlayPlot then
        return
    end
    self.isPlayPlot = true

    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(vo.id)
    local plotIds = CfUtils.Split(plotVo.plotIdGroup2)


    if isTask then
        --前置剧情
        if checkNumber(taskStoryType) == 1 then
            if checkNumber(plotVo.taskPlotId) > 0 then
                plotIds = nil
            else
                plotIds = CfUtils.Split(plotVo.taskPlotId)
            end
        else
            if checkNumber(plotVo.taskPlotEndId) > 0 then
                plotIds = nil
            else
                plotIds = CfUtils.Split(plotVo.taskPlotEndId)
            end
        end
    end
    if not plotIds then
        if endCb then
            endCb()
        end
        self.isPlayPlot = false
        return
    end

    self.curPlotIndex = 1
    self:PlayPloting(plotIds, vo, endCb, startCallback)
end

function MainQuestMapMgr:PlayPloting(plotIds, vo, endCb, startCallback)
    local cacheTimelineLoader = nil
    ChapterUtils.ProcessChapter(checkNumber(plotIds[self.curPlotIndex]), function(go)
        KTool.SetActive(URPCameraController.mainCamera, false)
        CS.UINavigationBarRoot.Instance:SetActive(false)
        self._plotGo = go
        if startCallback then
            startCallback()
        end
        -- print("[剧情] On start", self.curPlotIndex)
        -- 如果下一段是timeline剧情，预加载一下
        if self.curPlotIndex < table.count(plotIds) then
            local vo = ChapterUtils.GetChapterGeneralVo(checkNumber(plotIds[self.curPlotIndex + 1]))
            if vo and not string.isEmpty(vo.timelinePath) then
                cacheTimelineLoader = ResourceModule.LoadBundleAsync(vo.timelinePath)
                cacheTimelineLoader:Retain()
                -- print("[加载] 预加载", checkNumber(plotIds[self.curPlotIndex + 1]), vo.timelinePath)
            end
        end
    end, function()
        -- 如果是点了跳到op4的按钮，直接跳过当前关卡的所有剧情，然后去op4
        local skipOp = GameUtils.LoadInt("skip2Op4", 0) == 1
        if skipOp then
            GameUtils.SaveInt("skip2Op4", 2)
            self.curPlotIndex = table.count(plotIds)
        end
        
        -- print("[剧情] On end", self.curPlotIndex)
        --所有的播完结束
        if self.curPlotIndex >= table.count(plotIds) then
            KTool.SetActive(URPCameraController.mainCamera, true)
            self:PlayCurBgm()
            -- GameUtils.ShowBlackOverlay()
            if checkNumber(plotIds[self.curPlotIndex]) == 1000010 then
                -- 序章1剧情结束之后，要请求服务器，等服务器返回以后才进入下一关。
                -- 假如网络卡了，会露出背景，这里先遮黑，等下一关的loading出来再关闭遮黑
                GameUtils.ShowBlack(0.3, nil, function()
                    CS.UINavigationBarRoot.Instance:SetActive(true)
                    KTool.SafeDelete(self._plotGo)
                    self.isPlayPlot = false
                    if endCb then
                        endCb()
                    end
                end)
            else
                CS.UINavigationBarRoot.Instance:SetActive(true)
                KTool.SafeDelete(self._plotGo)
                self.isPlayPlot = false
                if endCb then
                    endCb()
                end
            end
        else
            self.curPlotIndex = self.curPlotIndex + 1
            KTool.SafeDelete(self._plotGo)
            self:PlayPloting(plotIds, vo, endCb)
        end
        -- 释放预加载的引用
        if cacheTimelineLoader then
            cacheTimelineLoader:Release()
            -- print("[加载] 释放预加载", checkNumber(plotIds[self.curPlotIndex]), vo.timelinePath)
        end
    end, nil, function()
        if checkNumber(plotIds[self.curPlotIndex]) == 1000202 then
            -- -- 创角前的这段剧情，结束时直接激活已经提前加载好的创角场景。无缝切换不用黑屏
            SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting32, true)
            return
        end
        if checkNumber(plotIds[self.curPlotIndex]) == 1000212 then
            -- 序章4最后一段剧情，结束以后要请求服务器记录关卡通关，等服务器返回以后再loading进入主界面
            GameUtils.ShowBlack(0.3)
            coroutine.yield(Yielders.GetWaitForSeconds(0.3))
        end
        -- 每段剧情之间加一个黑幕
        if self.curPlotIndex < table.count(plotIds) then
            GameUtils.ShowBlackDuration(0.4, 0.3, 0.4)
            coroutine.yield(Yielders.GetWaitForSeconds(0.4))
        end
    end)
end

