function MainQuestMapMgr:PlayCurBgm()
    local plotVo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(self._curSelectId)
    if not plotVo then
        return
    end

    local CriWareUtils =  import('Game.Entry.CriWareUtilsFix')
    --没配
    if checkString(plotVo.bgm) == "" then
        CriWareUtils.PlayRandomBGMFromCDList()
    else
        CriWareUtils.PlayMusicById(checkString(plotVo.bgm))
    end
end

function MainQuestMapMgr:PlayQuestStory(questId, type, cb)
    if self._isPlayStory then 
        return
    end
    self._isPlayStory = true

    local vo = QuestConfMgr:GetInstance():GetMainQuestPlotVo(questId)
    if not vo then
        if cb then
            cb()
        end
        self._isPlayStory = false
        return
    end

    local storyId = 0
    if type == StoryType.Begin then
        storyId = checkNumber(vo.plotIdGroup1)
    elseif type == StoryType.End then
        storyId = checkNumber(vo.plotIdGroup3)
    end

    --storyId = 1001041
    if storyId <= 0 then
        if cb then
            cb()
        end
        self._isPlayStory = false
        return
    end

    --不做0判断了  nil直接返回
    --local storyVo = self:GetChapterGeneralVo(storyId)
    --if not storyVo then
    --    return
    --end
    --local go = self:GetGo(storyVo.timelinePath)
    --if isNull(go) then
    --    return
    --end
    --KTool.SetActive(go, true)
    ChapterUtils.ProcessChapter(checkNumber(storyId), function(go)
        if not isNull(self._parGo) then
            KTool.SetActive(self._parGo, false)
        end
        self.chapterGo = go
    end, function()
        if not isNull(self._parGo) then
            KTool.SetActive(self._parGo, true)
        end
        if not isNull(self.chapterGo) then
            KTool.SafeDelete(self.chapterGo)
        end
        if cb then
            cb()
        end
        self._isPlayStory = false
    end)
    --[[
    local pd = KTool.GetComponent(go, typeof(CS.UnityEngine.Playables.PlayableDirector))
    if not isNull(pd) then
        pd:Pause()
        pd.time = 0
        pd:Play()
        --coroutine.yield(WaitForSeconds(3))
        coroutine.yield(WaitForSeconds(pd.duration))
        --播完回收
        self:PushGo(storyVo.timelinePath, go)
    end
    ]]
end

