function MainQuestMapMgr:GetGo(path)
    if not self._goPool then
        self._goPool = {}
    end
    path = checkString(path)
    if isNull(self._goPool[path]) then
        self._goPool[path] = {}
    end
    local t = self._goPool[path]
    if isNull(t[1]) then
        local loader = self:GetLoader(path)
        if not isNull(loader) then
            local go = CfUtils.InstantiateGo(loader.ResultObject, self._headParGo)
            return go
        else
            return nil
        end 
    end

    local go = t[1]
    table.remove(t, 1)
    return go
end

function MainQuestMapMgr:PushGo(path, go)
    if isNull(go) then
        return
    end

    if not self._goPool then
        self._goPool = {}
    end
    path = checkString(path)
    if isNull(self._goPool[path]) then
        self._goPool[path] = {}
    end

    table.insert(self._goPool[path], go)
    KTool.SetActive(go, false)
end

function MainQuestMapMgr:GetLoader(path)
    if not self._loaderPool then
        self._loaderPool = {}
    end
    path = checkString(path)
    if isNull(self._loaderPool[path]) then
        local loader = ResourceModule.LoadBundleSync(path)
        if loader.IsSuccess then
            self._loaderPool[path] = loader
        else
            loader:Release()
            return nil
        end
    end
    return self._loaderPool[path]
end

--回收资源
function MainQuestMapMgr:CollectionHeadInfo()
    if isNull(self._curHeadInfo) then
        return
    end
    for k, v in pairs(self._curHeadInfo) do
        self:PushGo(v.path, v.go)
    end
end


