function MainQuestMapMgr:GetChapterGeneralVo(id)
    id = checkNumber(id)
    if id <= 0 then
        return nil
    end
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting374, "ChapterGeneralVo", id)
    return vo
end


function MainQuestMapMgr:Clear()
    if not isNull(self._weatherGo) then
        GameObject.Destroy(self._weatherGo)
    end

    if not isNull(self._goPool) then
        for k, v in pairs(self._goPool) do
            GameObject.Destroy(v)
        end
    end

    if not isNull(self._parGo) then
        GameObject.Destroy(self._parGo)
    end

    if not isNull(self._loaderPool) then
        for k, v in pairs(self._loaderPool) do
            v:Release(true)
        end
    end

    if not isNull(self._weatherLoader) then
        self._weatherLoader:Release(true)
    end

    self:__delete()
    self.Destroy(self)   --这个好像没用
end

return MainQuestMapMgr
